// cloudflare workers maintenance page

const LOGO_BASE64 = ""
addEventListener('fetch', event => {
  event.respondWith(handleRequest(event.request));
});

async function handleRequest(request) {
  const url = 'https://155.190.60.28'; // Replace with your actual public IP
  try {
    const response = await fetch(url, { method: 'GET' });
    if (response.ok) {
      return response; // If the app is up, serve the app
    } else {
      throw new Error('App not responding');
    }
  } catch (error) {
    // Maintenance Page with Embedded Base64 Image
    return new Response(`
      <!DOCTYPE html>
      <html lang="en">
      <head>
        <meta charset="UTF-8">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
        <title>Maintenance Mode</title>
        <style>
          body {
            font-family: Arial, sans-serif;
            background-color: #f8f9fa;
            text-align: center;
            margin: 0;
            padding: 0;
          }
          .container {
            padding: 50px;
          }
          .logo {
            width: 400px;
            margin-bottom: 30px;
          }
          h1 {
            color: #333;
            font-size: 36px;
            margin-bottom: 10px;
          }
          p {
            color: #555;
            font-size: 18px;
            margin-bottom: 30px;
          }
          .footer {
            color: #999;
            font-size: 14px;
            margin-top: 50px;
          }
        </style>
      </head>
      <body>
        <div class="container">
          <img src="data:image/png;base64,${LOGO_BASE64}" alt="MyEngine Logo" class="logo">
          <h1>We’ll be back soon!</h1>
          <p>Our site is currently undergoing scheduled maintenance.<br>Thank you for your patience and understanding.</p>
          <p class="footer">&copy; 2024 MyEngine. All rights reserved.</p>
        </div>
      </body>
      </html>
    `, {
      status: 503,
      headers: { 'Content-Type': 'text/html' },
    });
  }
}
